<?php
require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/security.php';sh_require_admin();
$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){sh_verify_csrf();$action=$_POST['action']??'';$id=(int)($_POST['id']??0);
if($action==='delete'&&$id){sh_student_delete($db,$id);sh_audit($db,'delete','student',$id);$msg='Student and login account deleted.';}
if($action==='save'){$sid=trim($_POST['student_id']??'');$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$course=trim($_POST['course']??'');$year=(int)($_POST['year_level']??1);$mobile=trim($_POST['mobile']??'');$pw=(string)($_POST['password']??'');$sid=strtoupper($sid);if(!$sid||mb_strlen($name)<2||!filter_var($email,FILTER_VALIDATE_EMAIL)||!$course||$year<1||$year>8){$msg='Please enter valid student details.';}elseif(!$id&&strlen($pw)<8){$msg='Please set a login password of at least 8 characters.';}else{try{$db->begin_transaction();if($id){$s=$db->prepare('UPDATE students SET student_id=?,name=?,email=?,mobile=?,course=?,year_level=? WHERE id=?');$s->bind_param('sssssii',$sid,$name,$email,$mobile,$course,$year,$id);$s->execute();$s->close();sh_student_account_upsert($db,$id,$sid,$name,$email,$course,$year,$pw);sh_audit($db,'update','student',$id);}else{$s=$db->prepare('INSERT INTO students(student_id,name,email,mobile,course,year_level) VALUES(?,?,?,?,?,?)');$s->bind_param('sssssi',$sid,$name,$email,$mobile,$course,$year);$s->execute();$new=$s->insert_id;$s->close();sh_student_account_upsert($db,(int)$new,$sid,$name,$email,$course,$year,$pw);sh_audit($db,'create','student',$new);}$db->commit();$msg='Student saved. They can log in with their Student ID or email.';}catch(mysqli_sql_exception $e){$db->rollback();$msg=((int)$e->getCode()===1062)?'Student ID or email already exists.':'Database error while saving the student.';}}}
}
$q=trim($_GET['q']??'');$like='%'.$q.'%';$page=max(1,(int)($_GET['page']??1));$per=10;$offset=($page-1)*$per;$s=$db->prepare('SELECT COUNT(*) c FROM students WHERE name LIKE ? OR email LIKE ? OR course LIKE ? OR student_id LIKE ?');$s->bind_param('ssss',$like,$like,$like,$like);$s->execute();$total=(int)$s->get_result()->fetch_assoc()['c'];$s->close();$s=$db->prepare('SELECT * FROM students WHERE name LIKE ? OR email LIKE ? OR course LIKE ? OR student_id LIKE ? ORDER BY id DESC LIMIT ? OFFSET ?');$s->bind_param('ssssii',$like,$like,$like,$like,$per,$offset);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();
