<h1>Student Management</h1><?php if($msg):?><p class="p15-alert"><?=sh_e($msg)?></p><?php endif;?><section class="p15-card"><h2>Add student</h2><form class="p15-form" method="post"><input type="hidden" name="csrf" value="<?=sh_e(sh_csrf())?>"><input type="hidden" name="action" value="save"><label>Student ID<input name="student_id" required></label><label>Name<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>Mobile<input name="mobile"></label><label>Course<input name="course" required></label><label>Year<input type="number" name="year_level" min="1" max="8" value="1" required></label><label>Login password (min 8)<input type="password" name="password" minlength="8" autocomplete="new-password" required></label><button class="p15-btn">Add student</button></form></section><form class="p15-toolbar"><input name="q" value="<?=sh_e($q)?>" placeholder="Search name, email, course or ID"><button class="p15-btn">Search</button></form><div class="p15-card p15-table-wrap"><table class="p15-table"><thead><tr><th>ID</th><th>Name</th><th>Email</th><th>Course</th><th>Year</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=sh_e($r['student_id'])?></td><td><?=sh_e($r['name'])?></td><td><?=sh_e($r['email'])?></td><td><?=sh_e($r['course'])?></td><td><?=(int)$r['year_level']?></td><td><form method="post" data-confirm="Delete this student?"><input type="hidden" name="csrf" value="<?=sh_e(sh_csrf())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button>Delete</button></form></td></tr><?php endforeach;?></tbody></table></div><p><?php for($p=1;$p<=max(1,(int)ceil($total/$per));$p++):?> <a href="?q=<?=urlencode($q)?>&page=<?=$p?>"><?=$p?></a> <?php endfor;?></p><?php require __DIR__.'/../includes/app-footer.php';?>